/**
 * @file dl_backend_test.cc
 * @brief GoogleTest cases for the ONNX Runtime backend.
 *
 * Compiled only when CCTV_USE_ONNX_BACKEND is defined.  Each test loads
 * synthetic ONNX models from tests/fixtures/onnx/ which were generated by
 * models/convert/make_test_models.py.
 *
 * The fixture models are designed so that:
 *   yolo_test.onnx  -- always returns two detections (class 0, scores 0.92
 *                      and 0.85 in letterbox space).
 */

#if defined(CCTV_USE_ONNX_BACKEND)

#include "src/backend_onnx/onnx_backend.hpp"

#include <cstring>
#include <stdexcept>
#include <string>
#include <vector>

#include "cctv/cctv.h"
#include "gtest/gtest.h"

namespace {  // NOSONAR - anonymous ns is the C++ idiom for file-local linkage

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * @brief Returns the path to the tests/fixtures/onnx/ directory.
 *
 * CMake passes FIXTURES_DIR as a preprocessor definition.
 *
 * @side_effects None -- referentially transparent.
 */
const char* FixturesDir() noexcept {
#ifdef FIXTURES_DIR
  return FIXTURES_DIR;
#else
  return "tests/fixtures/onnx";
#endif
}

/**
 * @brief Builds the path to a fixture file.
 *
 * @side_effects None -- referentially transparent.
 */
std::string FixturePath(const char* filename) noexcept {
  return std::string(FixturesDir()) + "/" + filename;
}

// ---------------------------------------------------------------------------
// OnnxBackend unit tests
// ---------------------------------------------------------------------------

class OnnxBackendTest : public ::testing::Test {  // NOSONAR - test fixture
 protected:
  void SetUp() override { yolo_path_ = FixturePath("yolo_test.onnx"); }

  std::string yolo_path_;
};

TEST_F(OnnxBackendTest, ConstructSucceedsWithValidModels) {
  mep_cctv::backend_onnx::OnnxBackend backend(yolo_path_.c_str(), 0.5f, 0.45f);
  // Construction did not throw -- backend is ready.
  (void) backend;
  SUCCEED();
}

TEST_F(OnnxBackendTest, ConstructFailsWithNullYoloPath) {
  EXPECT_THROW(
      {
        const mep_cctv::backend_onnx::OnnxBackend backend(nullptr, 0.5f, 0.45f);
      },
      std::runtime_error);  // NOSONAR - test-only failure signal
}

TEST_F(OnnxBackendTest, ConstructFailsWithMissingYoloFile) {
  EXPECT_THROW(
      {
        const mep_cctv::backend_onnx::OnnxBackend backend(
            "/nonexistent/path/yolo.onnx", 0.5f, 0.45f);
      },
      std::exception);  // NOSONAR - test-only failure signal
}

TEST_F(OnnxBackendTest, DetectReturnsBoxesFromSyntheticModel) {
  mep_cctv::backend_onnx::OnnxBackend backend(yolo_path_.c_str(), 0.5f, 0.45f);

  // Prepare a black tensor at the configured model input size.
  const std::vector<float> tensor(
      static_cast<size_t>(mep_cctv::core::kInputElements), 0.0f);

  const mep_cctv::core::LetterboxParams params =
      mep_cctv::core::ComputeLetterboxParams(640, 640);

  const std::vector<cctv_box> boxes =
      backend.Detect(tensor.data(), params, 640, 640);

  // The synthetic model always produces two anchors with score >= 0.5.
  EXPECT_GE(static_cast<int>(boxes.size()), 1);
  for (const cctv_box& b : boxes) {
    EXPECT_EQ(0, b.class_id);
    EXPECT_GE(b.score, 0.5f);
    EXPECT_LE(b.score, 1.0f);
    EXPECT_GE(b.w, 0.0f);
    EXPECT_GE(b.h, 0.0f);
  }
}

// ---------------------------------------------------------------------------
// C ABI tests against the ONNX backend
// ---------------------------------------------------------------------------

class DlCApiTest : public ::testing::Test {  // NOSONAR - test fixture
 protected:
  void SetUp() override {
    yolo_path_ = FixturePath("yolo_test.onnx");
    cfg_.yolo_model_path = yolo_path_.c_str();
    cfg_.conf_threshold = 0.5f;
    cfg_.iou_threshold = 0.45f;
    engine_ = cctv_engine_create(&cfg_);
  }

  void TearDown() override {
    if (engine_ != nullptr) {
      cctv_engine_destroy(engine_);
      engine_ = nullptr;
    }
  }

  std::string yolo_path_;
  cctv_config cfg_{};
  cctv_engine* engine_ = nullptr;
};

TEST_F(DlCApiTest, EngineCreateSucceeds) { ASSERT_NE(nullptr, engine_); }

TEST_F(DlCApiTest, BackendNameIsDlOnnx) {
  const char* name = cctv_backend();
  ASSERT_NE(nullptr, name);
  EXPECT_STREQ("onnx", name);
}

TEST_F(DlCApiTest, DetectObjectsReturnsBoxes) {
  ASSERT_NE(nullptr, engine_);

  // 640x640 black frame.
  const std::vector<uint8_t> rgb(static_cast<size_t>(640 * 640 * 3),
                                 static_cast<uint8_t>(0));

  cctv_detections dets{};
  const cctv_status status =
      cctv_detect_objects(engine_, rgb.data(), 640, 640, &dets);

  EXPECT_EQ(CCTV_OK, status);
  // Synthetic model always produces at least one detection above 0.5 threshold.
  EXPECT_GE(dets.count, 1);
  EXPECT_NE(nullptr, dets.boxes);

  cctv_free_detections(&dets);
}

TEST_F(DlCApiTest, DetectObjectsBoxesWithinImageBounds) {
  ASSERT_NE(nullptr, engine_);

  const int w = 640;
  const int h = 640;
  const std::vector<uint8_t> rgb(static_cast<size_t>(w * h * 3),
                                 static_cast<uint8_t>(0));

  cctv_detections dets{};
  ASSERT_EQ(CCTV_OK, cctv_detect_objects(engine_, rgb.data(), w, h, &dets));

  for (int i = 0; i < dets.count; ++i) {
    const cctv_box& b = dets.boxes[i];
    EXPECT_GE(b.x, -1.0f) << "box " << i << " x negative";
    EXPECT_GE(b.y, -1.0f) << "box " << i << " y negative";
    EXPECT_LE(b.x + b.w, static_cast<float>(w) + 1.0f);
    EXPECT_LE(b.y + b.h, static_cast<float>(h) + 1.0f);
  }

  cctv_free_detections(&dets);
}

TEST_F(DlCApiTest, DetectAudioOnSilenceReportsNothing) {
  // Audio no longer goes through ONNX: cctv_detect_audio is the shared
  // code-based energy detector, identical in every backend. Silence must
  // therefore report nothing, whichever backend is compiled in.
  ASSERT_NE(nullptr, engine_);

  const std::vector<float> silence(16000, 0.0f);
  cctv_audio_result result{};
  const cctv_status status =
      cctv_detect_audio(engine_, silence.data(),
                        static_cast<int>(silence.size()), 16000, &result);

  EXPECT_EQ(CCTV_OK, status);
  EXPECT_EQ(0, result.person_present);
  EXPECT_NEAR(0.0f, result.score, 1e-6f);
}

TEST_F(DlCApiTest, EngineCreateFailsWithNullYoloPath) {
  cctv_config bad_cfg{};
  bad_cfg.yolo_model_path = nullptr;
  bad_cfg.conf_threshold = 0.5f;
  bad_cfg.iou_threshold = 0.45f;

  cctv_engine* bad_engine = cctv_engine_create(&bad_cfg);
  EXPECT_EQ(nullptr, bad_engine);
  if (bad_engine != nullptr) { cctv_engine_destroy(bad_engine); }
}

TEST_F(DlCApiTest, EngineCreateFailsWithMissingModelFile) {
  cctv_config bad_cfg{};
  bad_cfg.yolo_model_path = "/nonexistent/yolo.onnx";
  bad_cfg.conf_threshold = 0.5f;
  bad_cfg.iou_threshold = 0.45f;

  cctv_engine* bad_engine = cctv_engine_create(&bad_cfg);
  EXPECT_EQ(nullptr, bad_engine);
  if (bad_engine != nullptr) { cctv_engine_destroy(bad_engine); }
}

}  // namespace

#endif  // CCTV_USE_ONNX_BACKEND
